exercise.solution:
fn make_counter(step: i32) -> impl FnMut() -> i32 {
    let mut total = 0;
    move || {
        total += step;
        total
    }
}

fn sum_where(values: &[i32], mut keep: impl FnMut(i32) -> bool) -> i32 {
    values.iter().filter(|n| keep(**n)).sum()
}

struct Collatz {
    current: u64,
    done: bool,
}

impl Collatz {
    fn new(start: u64) -> Collatz {
        Collatz { current: start, done: false }
    }
}

impl Iterator for Collatz {
    type Item = u64;

    fn next(&mut self) -> Option<u64> {
        if self.done {
            return None;
        }
        let value = self.current;
        if value == 1 {
            self.done = true;
        } else if value % 2 == 0 {
            self.current = value / 2;
        } else {
            self.current = value * 3 + 1;
        }
        Some(value)
    }
}

fn main() {
    let mut by_three = make_counter(3);
    let mut by_ten = make_counter(10);
    let first = by_three();
    let second = by_three();
    let third = by_three();
    println!("{first} {second} {third}");
    let ten = by_ten();
    let fourth = by_three();
    println!("{ten} {fourth}");

    let numbers = [4, 9, -2, 15, 8, 0];
    let limit = 5;
    println!("{}", sum_where(&numbers, |n| n > limit));

    let mut checked = 0;
    let even_total = sum_where(&numbers, |n| {
        checked += 1;
        n % 2 == 0
    });
    println!("even total {even_total}, checked {checked}");
    println!("{}", sum_where(&[], |_| true));

    let steps: Vec<u64> = Collatz::new(6).collect();
    println!("{:?}", steps);
    println!("{:?}", Collatz::new(1).collect::<Vec<u64>>());
    println!("length from 27: {}", Collatz::new(27).count());
    println!("peak from 27: {:?}", Collatz::new(27).max());
    let scaled: Vec<u64> = Collatz::new(6).skip(5).map(|n| n * 100).collect();
    println!("{:?}", scaled);
}
